package org.firstinspires.ftc.teamcode.subsystems;

import com.pedropathing.drivetrain.DrivePowers;
import com.pedropathing.math.Pose;
import com.pedropathing.math.Velocity;
import com.pedropathing.revhub.drivetrains.Mecanum;
import com.pedropathing.revhub.localizers.PinpointLocalizer;
import com.qualcomm.robotcore.hardware.HardwareMap;

import org.firstinspires.ftc.teamcode.pedro.Constants;

// Generated by refract-suite ftc-construct. Teleop owner of the 4 drive motors and the Pinpoint.
// Autos use Pedro's Follower instead; never construct both in one OpMode.
// Without measured pod offsets there is no localizer: robot-centric driving only, no aim (DECODE always drove).
public class Drive {
    // a predicted stop further than this is not believed (a bad velocity reading), so the aim uses the real pose
    private static final double MAX_STOP_IN = 30, MAX_STOP_RAD = Math.PI / 2;

    private final PinpointLocalizer localizer;
    private final Mecanum drivetrain;

    public Drive(HardwareMap hardwareMap) {
        localizer = Constants.pinpointTuned() ? Constants.localizer(hardwareMap) : null;
        drivetrain = Constants.drivetrain(hardwareMap);
    }

    public boolean localized() {
        return localizer != null;
    }

    public void update() {
        if (localizer != null) localizer.update();
    }

    public Pose pose() {
        return localizer != null ? localizer.pose() : new Pose(0, 0, 0);
    }

    public Velocity velocity() {
        return localizer != null ? localizer.velocity() : Velocity.zero();
    }

    public void setPose(Pose pose) {
        if (localizer != null) localizer.setPose(pose);
    }

    // DECODE's Drivetrain.driveFieldOriented: stick angle minus robot heading, wheels from sin/cos(angle - 45 deg)
    // divided by the larger of the two, so any full stick gives full wheel power (diagonals too).
    // forward / right: stick axes as the driver sees them. driverHeading: field direction the drivers
    // face (red 0, blue PI). Passing driverHeading = pose().heading() gives plain robot-centric driving.
    // Pedro's DrivePowers is (forward, strafe left, turn CCW); Pedro scales all four down together past 1.
    public void driveFieldCentric(double forward, double right, double turnCcw, double driverHeading) {
        double power = Math.min(1, Math.hypot(forward, right));
        double angle = Math.atan2(forward, right) - (pose().heading() - driverHeading);
        double sin = Math.sin(angle - Math.PI / 4), cos = Math.cos(angle - Math.PI / 4);
        double max = Math.max(Math.abs(sin), Math.abs(cos));
        // DECODE: leftFront = power * cos / max, rightFront = power * sin / max; Pedro: lf = f - s, rf = f + s
        double lf = max < 1e-9 ? 0 : power * cos / max, rf = max < 1e-9 ? 0 : power * sin / max;
        drivetrain.drive(new DrivePowers((lf + rf) / 2, (rf - lf) / 2, turnCcw), true);
    }

    // Where the robot will have stopped if the sticks are let go now (null when Foresight is not tuned or the
    // answer is not believable). Pedro's own braking model (Foresight.getBrakeDisplacement): the stopping distance
    // along each robot axis is linear x v + quadratic x v|v|, the turn the same with the heading coefficients.
    // Manual driving brakes (MecanumConfig.manualBrakeMode defaults to true and Constants leaves it).
    public Pose stopPose() {
        if (localizer == null || !Constants.foresightTuned()) return null;
        Pose p = pose();
        Velocity v = velocity();
        double h = p.heading();
        double forward = v.vx * Math.cos(h) + v.vy * Math.sin(h);
        double left = -v.vx * Math.sin(h) + v.vy * Math.cos(h);
        double dForward = Constants.forwardBrakingLinearCoefficient * forward + Constants.forwardBrakingQuadraticCoefficient * forward * Math.abs(forward);
        double dLeft = Constants.strafeBrakingLinearCoefficient * left + Constants.strafeBrakingQuadraticCoefficient * left * Math.abs(left);
        double dHeading = Constants.headingBrakingLinearCoefficient * v.omega + Constants.headingBrakingQuadraticCoefficient * v.omega * Math.abs(v.omega);
        double mid = h + dHeading / 2;
        double x = p.x() + dForward * Math.cos(mid) - dLeft * Math.sin(mid);
        double y = p.y() + dForward * Math.sin(mid) + dLeft * Math.cos(mid);
        if (Double.isNaN(x + y + dHeading) || Math.hypot(x - p.x(), y - p.y()) > MAX_STOP_IN || Math.abs(dHeading) > MAX_STOP_RAD) return null;
        return new Pose(x, y, h + dHeading);
    }

    public void stop() {
        drivetrain.stop();
    }
}
